# DOS U preset: Monkey Island 1 (mi1kor Korean patch), 2 bpp anti-aliased.
# M1U*.SVF baked by tools/korean/scumm-fonts/m1u.tsv: dialogue, verbs and the
# sentence line in a gothic face, the title/credit card in a serif face.
# Cells per charset: cs0 22x24, cs1/cs3 16x16, cs2 18x18, cs4 26x24.
# Charsets that share a cell share one SVF. Licences: see M12FONT.TXT beside this file.
[hires]
scale=2
alpha=true
missing=u+25a1

[font.0]
bitmap=M1U0.SVF

[font.1]
bitmap=M1U1.SVF

[font.2]
bitmap=M1U2.SVF

[font.3]
bitmap=M1U1.SVF

[font.4]
bitmap=M1U4.SVF

[latin]
mode=proportional
metrics=font

# Codes the game did not use for what the code page says (mi1kor/hires_text.map).
[glyphs]
0x5e = keep

# Solid arrows in the 2bpp dialogue and card charsets; 0x5f is a real underscore elsewhere.
[glyphs:cs2]
0x5f = keep
0x7f = keep

[glyphs:cs4]
0x5f = keep
0x7f = keep
